local kTool = CS.Engine.Lib.KTool
local UIModule = CS.Engine.UI.UIModule

--- from: Assets/BundleResources/Prefabs/ResidentEvent/ResdientAdvertisementDialog.prefab > name: ResdientAdvertisementDialog
---@class AdvertisementDialog
---@field Env                           	AdvertisementDialog                     
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field GoodGroup3                    	UnityEngine.RectTransform               	0    
---@field GoodGroup2                    	UnityEngine.RectTransform               	1    
---@field GoodGroup1                    	UnityEngine.RectTransform               	2    
---@field CardNode                      	Engine.Modules.LuaBehaviour             	3    
---@field Slier                         	UnityEngine.UI.Slider                   	4    
---@field FontStyleButtonOneclick       	UnityEngine.RectTransform               	5    
---@field redPoint                      	UnityEngine.RectTransform               	6    
local AdvertisementDialog = Class('AdvertisementDialog')
function AdvertisementDialog:__init()
    self.adRewards = nil
    self.accumulatedAdRewards = nil
    self.currentViewNum =  0 
    self.adNodeCells = {}
    self.cellData = nil
    self.handler = nil
end
function AdvertisementDialog:__delete()
    self.adRewards = nil
    self.accumulatedAdRewards = nil
    self.adNodeCells = nil
    self.cellData = nil
    self.handler = nil
end

function AdvertisementDialog:Awake()
    self.handler = Events.AddListener("AD_EVENT", function(event)
        if self.cellData and event == 'OnRewardedAdReceivedRewardEvent' then
            --TODO 调用领取奖励接口
            GameUtils.Request(Interfaces.OverseaAdMallAdRewardsDraw, { id = self.cellData.id }, function(req, resp)
                if checkNumber(resp.errCode) == 0 then
                    local data = resp.data
                    local rewards = data.rewards
                    if #rewards > 0 then
                        GoodsUtils.DrawRewards(rewards)
                        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
                    end
                    local viewNum = checkInt(data.viewNum)
                    self.cellData.currentStock = checkNumber(self.cellData.currentStock) - 1
                    self:UpdateViewNum(viewNum)
                end
            end)
        end
    end)
end

function AdvertisementDialog:Start()
    ---@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local isPrivilegeCard = false
    if playerComponent then
        isPrivilegeCard = playerComponent:IsPrivilegeCard()
    end
    if isPrivilegeCard then
        kTool.SetActive(self.FontStyleButtonOneclick.gameObject , true)
        SetButtonAction(self.FontStyleButtonOneclick , function ()
            if isNull(self.adRewards) then
                return
            end
            local num = self:DrawRewardsNum()
            if num == 0  then
                GameUtils.Toast(localize("当前已无次数，次日刷新"))
                return
            end
            self:DrawRewards(0)
        end)
    else
        CfUtils.SetActive(self.FontStyleButtonOneclick, false)
    end
end

function AdvertisementDialog:Refresh()
    if self.accumulatedAdRewards then
        return
    end
    GameUtils.Request(Interfaces.OverseaAdMallAdRewards, {}, function(request, response)
        if checkNumber(response.errCode) == 0 then
            self.adRewards = response.data.adRewards
            self.accumulatedAdRewards = response.data.accumulatedAdRewards
            self.currentViewNum  = response.data.viewNum 
            self:UpdateUI() 
        end
    end)
end
--- func desc 刷新红点显示
function AdvertisementDialog:RefreshPoint()
     ---@type PlayerComponent
     local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
     local isPrivilegeCard = false
     if playerComponent then
         isPrivilegeCard = playerComponent:IsPrivilegeCard()
     end
    if isPrivilegeCard then
        local num = self:DrawRewardsNum()
        GameUtils.SetRedPointNum(Constants.RedPointConst.AdvertisementReward , 0)
        GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.AdvertisementReward)
        kTool.SetActive(self.redPoint.gameObject ,  num > 0)
        if num == 0  then
            CfUtils.WriteLocalData("AdvertisementReward" , os.date("%Y%m%d"))
        end
    end
end
--- func desc  奖励可以领取的数量
function AdvertisementDialog:DrawRewardsNum()
    local num = 0 
    for k, v in pairs(self.accumulatedAdRewards) do
        if checkInt(v.currentStock) > 0 then
            num = 1
            break
        end 
    end
    if num == 0 then
        for k, v in pairs(self.adRewards) do
            if checkInt(v.currentStock) > 0 then
                num = 1
                break
            end 
        end 
    end
    return num
end

function AdvertisementDialog:UpdateUI()
    local currentViewNum = checkInt(self.currentViewNum)
    local viewNum = checkInt(self.accumulatedAdRewards[#self.accumulatedAdRewards].viewNum) 
    local currentStock = checkInt(self.accumulatedAdRewards.currentStock)
    self.Slier.value = currentViewNum / viewNum
    if #self.adNodeCells == 0 then
        for i, adRew in pairs(self.adRewards) do
            ---@type UnityEngine.GameObject
            local gameObject = kTool.Instantiate(self.CardNode.transform.parent.gameObject ,self.CardNode.gameObject)
            kTool.SetActive(gameObject, true)
            ---@type AdvertisementCell
            local env =  CfUtils.GetLuaScr(gameObject , "Game.UI.Welfare.AdvertisementCell")
            self.adNodeCells[#self.adNodeCells+1] = env
        end   
    end
    for i, env in pairs(self.adNodeCells) do
        env:InitData(self.adRewards[i])
        env:RefreshUI(self, Bind(self, self.OnCellAction))
    end
    self:UpdateGroups()
    self:RefreshPoint()
end

function AdvertisementDialog:OnCellAction(cellData)
    ---@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local isPrivilegeCard = false

    if playerComponent then
        isPrivilegeCard = playerComponent:IsPrivilegeCard()
    end
    local currentStock = checkInt(cellData.currentStock)
    if currentStock == 0 then
        GameUtils.Toast(localize("当前已无次数，次日刷新"))
        return
    end
    local stock = cellData.stock
    if isPrivilegeCard then
        GameUtils.Request(Interfaces.OverseaAdMallAdRewardsDraw , {id = cellData.id }, function(req, resp)
            if checkNumber(resp.errCode) == 0 then
                local data = resp.data
                local rewards = data.rewards
                if #rewards > 0  then
                    GoodsUtils.DrawRewards(rewards)
                    UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
                end
                local viewNum = checkInt(data.viewNum)
                cellData.currentStock = currentStock - 1
                self:UpdateViewNum(viewNum)
            end
        end)
        return
    end

    if (kTool.UNITY_ANDROID() or kTool.UNITY_IOS()) and type(typeof(CS.FMaxSdkApp)) == 'userdata'  then
        self.cellData = cellData
        local KTool = CS.Engine.Lib.KTool
        ---@type FMaxSdkApp
        local maxSdkApp = KTool.GetComponent(CS.Game.Native.Game.Instance.gameObject, typeof(CS.FMaxSdkApp))
        if maxSdkApp.IsSdkInitialized then
            ---load success
            --maxSdkApp:ShowDebugger()
            if not maxSdkApp:IsRewardAdReady() then
                GameUtils.Toast(localize('广告未加载成功，请稍后重试'))
                return
            end
            maxSdkApp:ShowRewardAd()
            if currentStock == 0 then
                GameUtils.Toast(localize("已经没有观影次数"))
                return
            end
            xRecord.record('4-014', string.format("click_freepack_%s", tostring(cellData.id)))
            return
        end
    end

    GameUtils.Toast('觀影福利暫未開放，敬啟期待\n不影響特權用戶直接領取獎勵')
end

function AdvertisementDialog:UpdateGroups()
    local totalViewNum = checkInt(self.currentViewNum) 
    ---@type UnityEngine.GameObject
    local groups = {self.GoodGroup1 , self.GoodGroup2, self.GoodGroup3}
    for k, v in pairs(groups) do
        local GoodNode = v.transform:Find("GoodNode")
        ---@type GoodNodeMB
        local scr = CfUtils.GetLuaScr(GoodNode , "Game.Behaviours.GoodNodeMB")
        local data = self.accumulatedAdRewards[k] 
        local reward = data.rewards[1] or {}
        scr:Reload({
            goodsId = checkInt(reward.goodsId),
            text = string.format("x%d",checkInt(reward.num)),
            isShowNo = true
        })
        scr:SetClickCallback(function ()
            if checkInt(data.currentStock) == 0 or totalViewNum < checkInt(data.viewNum) then
                local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(reward.goodsId)
                GameUtils.ShowCommonTipsBoard(GoodNode, vo.name, vo.desc, vo.quality, vo.id, true)
                return
            end
            if totalViewNum >= checkInt(data.viewNum) then
                self:DrawRewards(data.id)
            end
        end)
       if checkInt(data.currentStock) == 0 then
            local UIFX_Available = v.transform:Find("UIFX_Available")
            kTool.SetActive(UIFX_Available.gameObject , false)
            scr:SetSanXingGainShow(true)
       elseif totalViewNum >= checkInt(data.viewNum)  then
            local UIFX_Available = v.transform:Find("UIFX_Available")
            kTool.SetActive(UIFX_Available.gameObject , true)
       end
       local TxtNum = v.transform:Find("TxtNum")
       local showNum = totalViewNum > checkInt(data.viewNum) and checkInt(data.viewNum) or totalViewNum
       CfUtils.FillText(TxtNum , string.format("%d/%d" , showNum , checkInt(data.viewNum)))
    end
end
function AdvertisementDialog:GetAccumulatedAdRewardsId(adId)
    local adId = checkInt(adId)
    for k, v in pairs(self.accumulatedAdRewards) do
        if checkInt(v.id) == adId then
            return v 
        end
    end

end
function AdvertisementDialog:DrawRewards(adId)
    --TODO 调用领取奖励接口
    GameUtils.Request(Interfaces.OverseaAdMallAdRewardsDraw, { id = adId}, function(req, resp)
        if checkNumber(resp.errCode) == 0 then
            local data = resp.data
            local rewards = data.rewards
            GoodsUtils.DrawRewards(rewards)
            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards , cb = function()
                if checkInt(adId) == 0 then
                    self.accumulatedAdRewards = nil
                    self:Refresh()
                    return
                end
                local data = self:GetAccumulatedAdRewardsId(adId)
                data.currentStock = data.currentStock - 1
                self:UpdateUI()
            end} })
        end
    end)
end

function AdvertisementDialog:UpdateViewNum(viewNum)
    self.currentViewNum = viewNum
    self:UpdateUI()
end

function AdvertisementDialog:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return AdvertisementDialog